def transform(grid):
    """Restore sparse off-palette pixels to the dominant region color."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    # The four most frequent colors form the background/object palette;
    # less frequent colors are isolated corruption marks.
    palette = set(v for v, _ in counts.most_common(4))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in palette:
                continue
            votes = Counter()
            for rr in range(max(0, r-1), min(h, r+2)):
                for cc in range(max(0, c-1), min(w, c+2)):
                    if (rr, cc) != (r, c) and grid[rr][cc] in palette:
                        votes[grid[rr][cc]] += 1
            if votes:
                best = max(votes.values())
                tied = [v for v, n in votes.items() if n == best]
                # On ties, prefer the closest same-color pixel; then the
                # more common underlying color.
                def tie_key(v):
                    d = min(abs(rr-r) + abs(cc-c)
                            for rr in range(max(0, r-1), min(h, r+2))
                            for cc in range(max(0, c-1), min(w, c+2))
                            if grid[rr][cc] == v)
                    return (d, -counts[v])
                out[r][c] = min(tied, key=tie_key)
            else:
                out[r][c] = counts.most_common(1)[0][0]
    return out
